package com.amar.slackclone.conversation;import com.amar.slackclone.user.User;import jakarta.persistence.*;import java.time.OffsetDateTime;
@Entity @Table(name="conversation_message_reactions",uniqueConstraints=@UniqueConstraint(columnNames={"message_id","user_id","emoji"})) public class ConversationMessageReaction{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="message_id")ConversationMessage message;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="user_id")User user;@Column(length=16)String emoji;@Column(name="created_at")OffsetDateTime createdAt;@PrePersist void create(){createdAt=OffsetDateTime.now();}public ConversationMessageReaction(){}public ConversationMessageReaction(ConversationMessage m,User u,String e){message=m;user=u;emoji=e;}public User getUser(){return user;}public String getEmoji(){return emoji;}}
